// Задание 6: Мостовая сигнализация (обрыв/замыкание шлейфа)
const int loopPin = 6;
const int relayPin = 11;

void setup() {
  Serial.begin(9600);
  pinMode(loopPin, INPUT_PULLUP); // Шлейф замкнут на землю
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, LOW);
}

void loop() {
  int state = digitalRead(loopPin);

  // Если шлейф цел (пин притянут к земле), state будет LOW
  // При обрыве шлейфа пин подтянется к 5В (HIGH)
  if (state == HIGH) {
    digitalWrite(relayPin, HIGH);
    Serial.println("Тревога! Обрыв шлейфа!");
  } else {
    digitalWrite(relayPin, LOW);
    Serial.println("Шлейф в норме.");
  }
  delay(500);
}
